/* Complete, browser-local demonstration workflows. No equipment connection. */
const op={asset:0,stage:-1,alarmSeverity:'All',alarmStatus:'All',camera:0,located:false};
window.op=op;
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const factoryIndex=()=>state.factory<0?0:state.factory;
const scopeName=()=>state.factory<0?'All factories':factories[state.factory].name;
const periodDays=()=>({'Today':1,'This week':7,'This month':30}[$('#period').value]||1);
const storeKey='lifescience.demo.v4';let saved={};try{saved=JSON.parse(localStorage.getItem(storeKey)||'{}')}catch{}
if(!saved||typeof saved!=='object'||Array.isArray(saved))saved={};saved.alarms??={};saved.jobs??={};saved.batches??={};saved.events??=[];saved.cameras??={};
function persist(){try{localStorage.setItem(storeKey,JSON.stringify(saved))}catch{const e=$('#storage-status');if(e)e.textContent='Changes last for this session only.'}}
function eventLog(message,area='Operations',f=factoryIndex()){saved.events.unshift({time:new Date().toISOString(),message,area,factory:f});saved.events=saved.events.slice(0,100);persist()}
const snapshots=[{quality:98.6,satisfaction:94,compliance:98,recall:.08,legal:0,delivery:96.1,supplier:1.5,defect:1.4,cost:9.6,downtime:1.1,energy:.81,reuse:71},{quality:98.1,satisfaction:93,compliance:97,recall:.1,legal:0,delivery:97.2,supplier:1.7,defect:1.9,cost:8.6,downtime:.8,energy:.79,reuse:73},{quality:97.8,satisfaction:89,compliance:94,recall:.14,legal:1,delivery:92.4,supplier:2.3,defect:2.2,cost:6.4,downtime:1.3,energy:.94,reuse:61},{quality:98.2,satisfaction:92,compliance:96,recall:.08,legal:1,delivery:95.6,supplier:2.1,defect:1.8,cost:7.4,downtime:.7,energy:.86,reuse:67}];
function snapshot(){if(state.factory>=0)return snapshots[state.factory];return {quality:98.2,satisfaction:92,compliance:96,recall:.1,legal:2,delivery:95.4,supplier:1.9,defect:1.8,cost:32,downtime:3.9,energy:.84,reuse:68}}
const lineSpecs=[{name:'Tablet blister line',product:'Tablets · 500 mg',target:120000,output:96000,reject:.8,availability:94,performance:89,quality:98,utilization:82,progress:80,status:'Running',stage:'Sealing'},{name:'Capsule cartoning line',product:'Capsules · 250 mg',target:140000,output:106000,reject:1.1,availability:91,performance:87,quality:97,utilization:76,progress:76,status:'Changeover',stage:'Changeover'},{name:'Sterile vial filling line',product:'Sterile vials',target:160000,output:116000,reject:1.4,availability:92,performance:88,quality:99,utilization:85,progress:72,status:'Running',stage:'Inspection'}];
function lineData(i){const s=lineSpecs[i],factor=state.factory<0?1:factories[state.factory].output/428640,days=periodDays();return {...s,output:Math.round(s.output*factor*days),target:Math.round(s.target*factor*days),workOrder:'WO-'+(26042+factoryIndex()*10+i)}}
const assets=[{id:'P-104',name:'Transfer pump',area:'Process',skill:'Mechanical',health:78,risk:'Inspection recommended',cost:42000,reading:'Vibration 4.8 mm/s',target:'Vibration below 4.5 mm/s',due:'Next changeover',model:'pump'},{id:'M-201',name:'Packaging drive motor',area:'Packaging',skill:'Electrical',health:96,risk:'Healthy',cost:0,reading:'Temperature 62°C',target:'Temperature below 75°C',due:'Monthly inspection',model:'motor'},{id:'C-01',name:'Air compressor',area:'Facility',skill:'Utilities',health:89,risk:'Planned service',cost:12000,reading:'Pressure 6.2 bar',target:'Operating range 6.0–6.5 bar',due:'14 Nov 2026',model:'compressor'}];
const people=[{id:'T01',name:'Omar Hassan',role:'Mechanical technician',skills:['Mechanical'],valid:true,expiry:'30 Nov 2026'},{id:'T02',name:'Ali Mostafa',role:'Utilities engineer',skills:['Utilities'],valid:true,expiry:'15 Dec 2026'},{id:'T03',name:'Nour Ahmed',role:'Electrical technician',skills:['Electrical'],valid:true,expiry:'31 Jan 2027'},{id:'T04',name:'Sara Mahmoud',role:'Mechanical technician',skills:['Mechanical'],valid:false,expiry:'Expired 31 Oct 2026'}];
function modelSlot(kind,index=0,large=false){return `<div class="model-view ${large?'model-large':''}" data-model="${kind}" data-index="${index}" aria-label="Interactive ${kind} model"><div class="model-fallback">${kind==='factory'?factoryPlan():machine(index+1)}<small>Interactive model loading · schematic fallback</small></div><div class="model-hint">Drag to rotate · Scroll to zoom</div></div>`}
function opButton(text,action,kind=''){return `<button class="${kind}" onclick="${action}">${text}</button>`}
const baseOpenModal=openModal;openModal=function(title,body){$('#modalbody').innerHTML=`<div class="modal-title"><h2>${title}</h2><span class="pill">Demonstration</span></div><div class="modal-content">${body}</div>`;$('#modal').classList.remove('document-mode','wide-modal');$('#modal').showModal()};
const preOperationsMetrics=pageMetrics;pageMetrics=function(){const s=snapshot(),d=periodDays(),factor=state.factory<0?1:factories[state.factory].output/428640;if(state.tab==='Packaging'){const lines=lineSpecs.map((_,i)=>lineData(i)),out=lines.reduce((a,l)=>a+l.output,0),target=lines.reduce((a,l)=>a+l.target,0);return [['Packaging plan attainment',(out/target*100).toFixed(1)+'%','Target 95%'],['Units packaged',nfmt(out/1000)+'k','Selected period'],['Packaging reject rate',(lines.reduce((v,l)=>v+l.output*l.reject,0)/out).toFixed(1)+'%','Target below 1.5%'],['Delivery orders at risk',state.factory===2||state.factory<0?'2':'0','Recovery plan available']]};if(state.tab==='Process'){const b=scopedBatches();return [['Active batches',b.filter(x=>x.status!=='Complete').length,'Selected line'],['On hold',b.filter(x=>x.status==='Held').length,'Review and recovery'],['Batch plan attainment','94.8%','Schedule performance'],['Ready for packaging',b.filter(x=>x.stage===4).length,'Available for handover']]};if(state.tab==='Production Overview')return [['Production plan attainment',state.factory===2?'89.2%':'94.8%','Target 95%'],['Production output',Math.round(428640*factor*d).toLocaleString(),'Finished units'],['Capacity utilization',(state.factory===2?76:84)+'%','Target 85%'],['On-time delivery',s.delivery+'%','Target 93%']];if(state.tab==='Quality')return [['First-pass yield',s.quality+'%','Target 98%'],['Batches on hold',scopedBatches(true).filter(b=>b.status==='Held').length,'Review required'],['Cost of poor quality','EGP '+nfmt(s.cost*d)+'k','Selected period'],['Compliance',s.compliance+'%','Target 100%']];if(state.tab==='Maintenance')return [['Asset availability','97.8%','Target 97%'],['Open work orders',assets.filter((a,i)=>jobFor(i).status!=='Completed').length,'Selected factory'],['Planned work completed',Math.round(assets.filter((a,i)=>jobFor(i).status==='Completed').length/3*100)+'%','Local demo work orders'],['Production value at risk','EGP '+nfmt(assets.reduce((v,a,i)=>v+(jobFor(i).status==='Completed'?0:a.cost),0)/1000)+'k','Illustrative impact']];if(state.tab==='Workforce Mgmt')return [['Shift coverage','100%','148 people on shift'],['Training eligibility',Math.round(people.filter(p=>p.valid).length/people.length*100)+'%','Qualified sample roster'],['Available technicians',people.filter(p=>p.valid).length,'Across required skills'],['Assigned jobs',assets.filter((a,i)=>jobFor(i).assignee).length,'Selected factory']];if(state.tab==='Facility')return [['Facility availability','99.4%','No critical disruption'],['Utility spend','EGP '+nfmt(148*factor*d)+'k','Selected period'],['Controlled areas ready','98%','Within environment limits'],['Open facility alarms',visibleAlarms().filter(a=>a.area==='Facility'&&alarmStatus(a.id)!=='Resolved').length,'Review impact']];return preOperationsMetrics()};
function packagingView(){const l=lineData(state.line);return `<div class="business-strip"><strong>Production outlook</strong><span>${state.line===1?'Line 2 changeover is the main constraint. Review delivery impact and the recovery plan.':'Select a packaging line to review its performance, documents and downstream commitments.'}</span></div><div class="pack-layout"><section class="panel"><div class="panelhead"><div><h2>Packaging lines</h2><small>Select a line to update its performance details</small></div><span class="pill">3 lines</span></div><div class="pack-lines">${lineSpecs.map((_,i)=>{const x=lineData(i);return `<article class="pack-line ${i===state.line?'selected':''}"><button class="line-select" onclick="selectPackagingLine(${i})" aria-label="Select line ${i+1}"><strong>LINE ${i+1}</strong><span class="pill ${i===1?'amber-pill':''}">${x.status}</span></button><div class="pack-model-button" role="button" tabindex="0" onclick="if(state.line!==${i})selectPackagingLine(${i})" onkeydown="if(event.key==='Enter')selectPackagingLine(${i})">${modelSlot('packaging',i)}</div><div class="stats">${[['Work order',x.workOrder],['Product',x.product],['Target',nfmt(x.target/1000)+'k units'],['Produced',nfmt(x.output/1000)+'k units'],['Rejected',x.reject+'%']].map(r=>`<div><span>${r[0]}</span><b>${r[1]}</b></div>`).join('')}</div><div class="line-progress"><small>Progress</small><div class="bar"><i style="width:${x.progress}%"></i></div><strong>${x.progress}%</strong></div></article>`}).join('')}</div></section><div class="pack-right"><section class="panel pack-detail"><div class="panelhead"><h2>Line ${state.line+1} · Performance</h2><span class="positive"><span class="dot"></span> Demo telemetry</span></div><div class="station-buttons">${['Feeder','Sealing','Inspection','Cartoning'].map((t,i)=>opButton(t,`packStation(${i})`)).join('')}</div>${modelSlot('packaging',state.line,true)}<div class="row"><span>Current stage</span><strong class="${state.line===1?'warning':'positive'}">${l.status==='Running'?'Production running':'Changeover in progress'}</strong></div><div class="bar"><i style="width:${l.progress}%"></i></div><div class="actions">${opButton('Documents →',"documentCenter('Packaging')")}${opButton('Batch details →','packBatchDetails()')}${opButton('Recovery plan →','openAction(0)')}</div></section><div class="pack-gauges">${compactGauge('Availability',l.availability+'%',l.availability,0)}${compactGauge('Performance',l.performance+'%',l.performance,0)}${compactGauge('Quality',l.quality+'%',l.quality,0)}</div></div></div><div class="board-guidance">Select a line, station or metric to inspect details. Models are illustrative, unbranded 3D equipment.</div>`}
function selectPackagingLine(i){state.line=i;render()}
function packStation(i){const t=['Feeder','Sealing','Inspection','Cartoning'][i];openModal(t+' · Line '+(state.line+1),`<p>${['Material supply is sufficient for the current order. Replenishment is due in 2 hours.','Sealing is within the sample operating window. No open quality hold.','Vision inspection is checking presentation and completeness. Rejected units are separated for review.','Cartoning output is synchronized with the downstream dispatch plan.'][i]}</p><div class="modal-metrics"><div><small>Business impact</small><h3>${state.line===1?'Changeover affects line output':'On track'}</h3></div><div><small>Line utilization</small><h3>${lineData(state.line).utilization}%</h3></div></div><div class="actions">${opButton('Station manual',"documentCenter('Packaging')")}${opButton('Related alarms',"alarmCenter()")}</div>`)}
function packBatchDetails(){const b=scopedBatches().find(b=>b.stage===4)||scopedBatches()[0];batchDetail(b.id)}
const productionBeforeOps=production;production=function(){return state.tab==='Packaging'?packagingView():productionBeforeOps()};
function factoryPlan(){return `<svg viewBox="0 0 650 360" aria-label="Factory navigation schematic"><path d="M30 70h590v260H30z" fill="#c9e4d11a" stroke="#c8ffe477"/>${['Facility','Process','Packaging','Quality','Maintenance','Workforce Mgmt'].map((t,i)=>{let x=60+(i%3)*190,y=100+Math.floor(i/3)*110;return `<g role="button" tabindex="0" onclick="go('${t}')" onkeydown="if(event.key==='Enter')go('${t}')" style="cursor:pointer"><path d="M${x} ${y}l130 -25 30 30 -130 25Z" fill="#a5edda66" stroke="#c4ffe6"/><path d="M${x} ${y}v48l130 5V${y+5}Z" fill="#64959688"/><path d="M${x+130} ${y+5}l30 -30v48l-30 30Z" fill="#b5d8c655"/><text x="${x+70}" y="${y+78}" fill="#fff" text-anchor="middle" font-size="13">${t}</text></g>`}).join('')}</svg>`}
factory=function(){return `<div class="business-strip"><strong>Factory outlook</strong><span>Explore the site, inspect readiness and connect performance to actions.${op.located?' '+assets[op.asset].id+' is highlighted in the '+assets[op.asset].area+' area.':''}</span></div><div class="factory-explore"><section class="panel"><div class="panelhead"><div><h2>${scopeName()} · Factory explorer</h2><small>Select a building to open its business view</small></div>${opButton('Reset view',"resetModel('factory')")}</div>${modelSlot('factory',0,true)}<div class="area-shortcuts">${['Facility','Process','Packaging','Quality','Maintenance','Workforce Mgmt'].map(t=>opButton(t,`go('${t}')`)).join('')}</div></section><section class="panel"><h2>Site readiness</h2>${[['Production','94.8% of plan'],['Quality',snapshot().quality+'% first-pass yield'],['Delivery',snapshot().delivery+'% on time'],['Maintenance',assets.filter((a,i)=>jobFor(i).status!=='Completed').length+' open actions']].map(r=>`<div class="factory-row row"><strong>${r[0]}</strong><span class="positive">${r[1]}</span></div>`).join('')}<div class="actions">${opButton('Camera views',"cameraCenter()")}${opButton('Weather',"weatherCenter()")}${opButton('Alarm register',"alarmCenter()")}${opButton('Factory documents',"documentCenter('Factory')")}</div><div class="insight">${state.factory<0?'Choose a specific factory for local work orders and camera sources.':'Factory-specific records and assignments are stored in this browser for the demo.'}</div></section></div><div class="analytics-grid" style="margin-top:18px">${analyticsChart('Factory output','Finished production',scopeData().labels,[48,61,70,84,89,76.64].map(v=>+(v*scopeData().total).toFixed(2)),'k units')}${analyticsChart('Capacity utilization','Productive time as a share of available time',['Line 1','Line 2','Line 3'],lineSpecs.map(l=>l.utilization),'%',{type:'bar',target:85})}</div>`};
const batchStages=['Preparation','Processing','Quality review','Transfer','Ready for packaging'];
const allBatches=factories.flatMap((f,fi)=>lineSpecs.flatMap((l,li)=>[0,1].map(n=>({id:`BT-${26000+fi*100+li*10+n}`,factory:fi,line:li,product:l.product,stage:n===0?1:li===1?2:4,status:n===0?'Running':li===1?'Held':'Ready',progress:n===0?45:n===1&&li===1?65:95,units:li===0?48000:li===1?53000:58000}))));
function scopedBatches(allLines=false){return allBatches.filter(b=>(state.factory<0||b.factory===state.factory)&&(allLines||b.line===state.line)).map(b=>({...b,...saved.batches[b.id]}))}
function findBatch(id){const b=allBatches.find(b=>b.id===id);return b?{...b,...saved.batches[id]}:null}
processView=function(){const b=scopedBatches(),counts=batchStages.map((_,i)=>b.filter(x=>x.stage===i&&x.status!=='Complete').length),visible=op.stage<0?b:b.filter(x=>x.stage===op.stage);return `<div class="business-strip"><strong>Process flow</strong><span>Track batch progress, release constraints and readiness for packaging. Controls below affect this demonstration only.</span></div><section class="panel"><div class="panelhead"><div><h2>Batch journey · Line ${state.line+1}</h2><small>${scopeName()} · Select a stage to filter the batch list</small></div>${opButton('All stages','op.stage=-1;render()')}</div><div class="stage-grid">${batchStages.map((t,i)=>`<button class="stage ${op.stage===i?'active':''}" onclick="op.stage=${i};render()"><span class="stage-number">0${i+1}</span><strong>${t}</strong><b>${counts[i]} <small>batches</small></b><span class="${i===2&&counts[i]?'warning':'positive'}">${i===2&&counts[i]?'Review required':'View stage'}</span></button>`).join('')}</div></section><div class="analytics-grid" style="margin-top:18px"><section class="panel"><div class="panelhead"><h2>${op.stage<0?'Batch execution':batchStages[op.stage]+' queue'}</h2><span class="pill">DEMO CONTROLS</span></div><div class="table-scroll"><table><tr><th>Batch</th><th>Factory</th><th>Stage</th><th>Status</th><th></th></tr>${visible.map(x=>`<tr><td>${x.id}<br><small>${x.product}</small></td><td>${factories[x.factory].city}</td><td>${batchStages[x.stage]}</td><td class="${x.status==='Held'?'warning':'positive'}">${x.status}</td><td>${opButton('Review',`batchDetail('${x.id}')`)}</td></tr>`).join('')||'<tr><td colspan="5">No batches in this stage.</td></tr>'}</table></div></section><section class="panel"><h2>Handover & business impact</h2><div class="insight"><strong class="warning">${b.filter(x=>x.status==='Held').length} batch(es) on hold</strong><br>Resolve review holds before transfer to protect packaging start times.</div><div class="insight"><strong class="positive">${counts[4]} batches ready</strong><br>Prioritize batches linked to the earliest delivery commitments.</div><div class="actions">${opButton('Quality monitoring',"go('Quality')")}${opButton('Batch procedures',"documentCenter('Process')")}${opButton('Process alarms',"alarmCenter()")}</div></section></div>`};
function batchDetail(id){const b=findBatch(id);if(!b)return;openModal(b.id+' · Batch execution',`<div class="scope-label">${factories[b.factory].name} / Line ${b.line+1} / ${b.product}</div><div class="modal-metrics"><div><small>Current stage</small><h3>${batchStages[b.stage]}</h3></div><div><small>Status</small><h3>${b.status}</h3></div><div><small>Planned quantity</small><h3>${nfmt(b.units)} units</h3></div><div><small>Business impact</small><h3>${b.status==='Held'?'Packaging at risk':'On schedule'}</h3></div></div><div class="bar"><i style="width:${b.progress}%"></i></div><p>Demo execution: advance a stage, place the batch on hold, or resume after review. These controls never send equipment commands.</p><div class="actions">${b.status==='Complete'?'Completed demo batch.':b.status==='Held'?opButton('Review & resume demo',`batchAction('${id}','resume')`):opButton(b.stage===4?'Complete demo batch':'Advance demo stage',`batchAction('${id}','advance')`)+opButton('Hold demo batch',`batchAction('${id}','hold')`)}${opButton('Batch procedure',"documentCenter('Process')")}</div>`)}
function batchAction(id,action){const b=findBatch(id);if(!b||b.status==='Complete')return;if(action==='hold')b.status='Held';else if(action==='resume'&&b.status==='Held')b.status=b.stage===4?'Ready':'Running';else if(action==='advance'&&b.status!=='Held'){if(b.stage===4){b.status='Complete';b.progress=100}else{b.stage++;b.progress=Math.min(95,25+b.stage*18);b.status=b.stage===4?'Ready':'Running'}}else return;saved.batches[id]={stage:b.stage,status:b.status,progress:b.progress};eventLog(id+': '+action+' — '+batchStages[b.stage],'Process',b.factory);render();batchDetail(id)}
const demoAlarms=factories.flatMap((f,fi)=>[{id:`AL-${fi}-01`,factory:fi,area:'Packaging',severity:'High',title:'Line 2 output below recovery plan',impact:'2 customer orders may be delayed',asset:'Line 2',reading:'76% progress against planned order',time:'09:42'},{id:`AL-${fi}-02`,factory:fi,area:'Maintenance',severity:'Medium',title:'Pump P-104 vibration advisory',impact:'EGP 42k illustrative value at risk',asset:'P-104',reading:'4.8 mm/s; advisory threshold 4.5 mm/s',time:'09:35'},{id:`AL-${fi}-03`,factory:fi,area:'Facility',severity:'Low',title:'AHU-03 filter inspection due',impact:'Plan inspection before production is affected',asset:'AHU-03',reading:'Filter service interval reached',time:'09:20'}]);
function visibleAlarms(){return demoAlarms.filter(a=>state.factory<0||a.factory===state.factory)}function alarmStatus(id){return saved.alarms[id]||'Open'}
function alarmCenter(){const list=visibleAlarms().filter(a=>(op.alarmSeverity==='All'||a.severity===op.alarmSeverity)&&(op.alarmStatus==='All'||alarmStatus(a.id)===op.alarmStatus));openModal('Alarm register',`<div class="scope-label">${scopeName()} · Business-impact alerts · Simulated records</div><div class="filter-row"><label>Severity<select onchange="op.alarmSeverity=this.value;alarmCenter()">${['All','High','Medium','Low'].map(x=>`<option ${op.alarmSeverity===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Status<select onchange="op.alarmStatus=this.value;alarmCenter()">${['All','Open','Acknowledged','Resolved'].map(x=>`<option ${op.alarmStatus===x?'selected':''}>${x}</option>`).join('')}</select></label>${opButton('Export alarms',"exportReport('alarms')")}</div><div class="alarm-list">${list.map(a=>`<article><div class="row"><strong>${a.title}</strong><span class="pill ${a.severity==='High'?'amber-pill':''}">${a.severity}</span></div><small>${factories[a.factory].name} · ${a.area} · ${a.time} · ${alarmStatus(a.id)}</small><p>${a.impact}</p><div class="actions">${opButton('Evidence & timeline',`alarmDetail('${a.id}')`)}${opButton('Open area',`navigateAlarm('${a.id}')`)}${alarmStatus(a.id)==='Open'?opButton('Acknowledge',`setAlarm('${a.id}','Acknowledged')`):''}${alarmStatus(a.id)!=='Resolved'?opButton('Resolve demo',`setAlarm('${a.id}','Resolved')`):''}</div></article>`).join('')||'<p>No alarms match these filters.</p>'}</div>`);$('#modal').classList.add('wide-modal')}
function alarmDetail(id){const a=demoAlarms.find(x=>x.id===id);openModal(a.title,`<div class="modal-metrics"><div><small>Evidence</small><h3>${a.reading}</h3></div><div><small>Business impact</small><h3>${a.impact}</h3></div></div><ol class="timeline"><li>${a.time} — Monitoring rule raised ${id}.</li><li>${a.time} — ${a.asset} linked to ${a.area}.</li><li>Current state: ${alarmStatus(id)}.</li>${saved.events.filter(e=>e.message.includes(id)).map(e=>`<li>${new Date(e.time).toLocaleTimeString()} — ${escapeHTML(e.message)}</li>`).join('')}</ol><div class="actions">${opButton('Open affected area',`navigateAlarm('${id}')`)}${opButton('Back to register','alarmCenter()')}</div>`)}
function setAlarm(id,status){saved.alarms[id]=status;const a=demoAlarms.find(a=>a.id===id);eventLog(id+' '+status,a.area,a.factory);alarmCenter()}
function navigateAlarm(id){const a=demoAlarms.find(a=>a.id===id);$('#modal').close();state.factory=a.factory;state.line=a.area==='Packaging'?1:0;op.asset=0;go(a.area)}
function documentRecords(){return [{id:'URS-001',area:'Factory',title:'User requirements specification',version:'1.2',sections:[['Purpose','Provide a unified business view across factories with controlled drill-down to departments, lines and assets.'],['Functional requirements','The solution shall support factory selection, business KPI monitoring, alarms, batch tracking, document access and maintenance assignment.'],['Data requirements','Production, quality, delivery and sustainability data shall have a source, timestamp, unit and quality state.'],['Acceptance','Factory selection updates scoped views. Demo controls remain clearly separated from live integrations.']]},{id:'FDS-001',area:'Process',title:'Functional design specification',version:'1.1',sections:[['Navigation','Enterprise → Factory → Area → Line / Asset. Selectors and breadcrumbs preserve operating context.'],['Batch workflow','Preparation → Processing → Quality review → Transfer → Ready for packaging. Held batches cannot advance until resumed after review.'],['Alarms','Each alert carries severity, affected asset, business impact, status and event history.'],['Interfaces','Demonstration data is browser-local. Production adapters, authorization and audit storage are deployment work.']]},{id:'SOP-PKG-01',area:'Packaging',title:'Packaging operating procedure',version:'2.0',sections:[['Readiness','Confirm approved batch identity, line clearance, material availability and applicable checks.'],['Monitoring','Review output against plan, reject rate and downstream delivery commitments.'],['Exceptions','Record quality holds and deviations. Follow approved site procedures before any live restart.'],['Demo note','This sample document is for interface demonstration and is not an approved manufacturing procedure.']]},{id:'MAN-P104',area:'Maintenance',title:'Pump P-104 equipment manual',version:'1.0',sections:[['Asset identity','P-104 · Process transfer pump · Mechanical maintenance skill required.'],['Illustrative operating limits','Vibration advisory at 4.5 mm/s. Sample observed value 4.8 mm/s. Actual limits must come from the equipment manufacturer.'],['Maintenance planning','Inspect coupling, alignment and bearing condition during a planned production window.'],['Related records','Condition trend, maintenance work order and technician eligibility are available in this dashboard.']]},{id:'CIP-VAL-01',area:'Quality',title:'CIP validation checklist',version:'1.3',sections:[['Cycle coverage','Record pre-rinse, caustic wash, intermediate rinse and final rinse.'],['Quality review','Review temperature, flow, conductivity, phase duration and final-cycle result against the validated recipe.'],['Exceptions','Failed or incomplete criteria require review before release.'],['Demo note','Sample values and limits are illustrative; this is not a validated cleaning protocol.']]}]}
function documentCenter(area='All',id=''){const docs=documentRecords(),filtered=area==='All'?docs:docs.filter(d=>d.area===area||d.area==='Factory'),doc=docs.find(d=>d.id===id)||filtered[0]||docs[0];op.documentId=doc.id;openModal('Documents',`<div class="document-workspace"><aside>${docs.map(d=>`<button class="${d.id===doc.id?'active':''}" onclick="documentCenter('All','${d.id}')"><strong>${d.id}</strong><small>${d.title}</small></button>`).join('')}</aside><article class="document-sheet"><div class="row"><span class="pill">SAMPLE · NOT APPROVED FOR USE</span><small>Version ${doc.version}</small></div><h1>${doc.title}</h1><small>${scopeName()} · ${doc.area}</small>${doc.sections.map(s=>`<h3>${s[0]}</h3><p>${s[1]}</p>`).join('')}<div class="actions">${opButton('Download document',`downloadDocument('${doc.id}')`)}${opButton('Print / save PDF',`printDocument('${doc.id}')`)}</div></article></div>`);$('#modal').classList.add('wide-modal','document-mode')}
function downloadable(name,content,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function documentHTML(id){const d=documentRecords().find(d=>d.id===id);return `<!doctype html><html><head><meta charset="UTF-8"><title>${d.id}</title><style>body{font:15px Arial;max-width:800px;margin:40px auto;line-height:1.7;color:#263039}h1{font-size:28px}small{color:#68717b}header{border-bottom:2px solid #78bbaa;padding:15px 0}</style></head><body><header><strong>SAMPLE — NOT APPROVED FOR MANUFACTURING USE</strong></header><h1>${d.title}</h1><small>${d.id} · Version ${d.version} · ${scopeName()}</small>${d.sections.map(s=>`<h3>${s[0]}</h3><p>${s[1]}</p>`).join('')}</body></html>`}
function downloadDocument(id){downloadable(id+'.html',documentHTML(id),'text/html;charset=utf-8')}
function printHTML(html){const w=window.open('','_blank');if(!w){openModal('Print preview blocked','Allow popups for this dashboard, or download the report instead.');return}w.document.write(html);w.document.close();w.focus();setTimeout(()=>w.print(),250)}
function printDocument(id){printHTML(documentHTML(id))}
function jobFor(i,f=factoryIndex()){return saved.jobs[f+'-'+i]||{assignee:'',status:'Open',note:''}}
function maintenanceView(){const a=assets[op.asset],j=jobFor(op.asset);return `<div class="business-strip"><strong>Maintenance outlook</strong><span>Inspect health, locate equipment, assign qualified people and retain a maintenance record.</span></div><div class="asset-layout"><section class="panel asset-directory"><h2>Asset register</h2>${assets.map((x,i)=>`<button class="asset-choice ${op.asset===i?'active':''}" onclick="op.asset=${i};render()"><strong>${x.id} · ${x.name}</strong><small>${x.area} · ${x.risk}</small><div class="bar"><i style="width:${x.health}%"></i></div><span>${x.health}% health · ${jobFor(i).status}</span></button>`).join('')}</section><section class="panel"><div class="panelhead"><div><h2>${a.id} · ${a.name}</h2><small>${scopeName()} / ${a.area}</small></div><span class="pill">${j.status}</span></div>${modelSlot(a.model,op.asset,true)}<div class="actions">${opButton('Locate in factory','locateAsset()')}${opButton('Piping view','pipeView()')}${opButton('Asset documents',"documentCenter('Maintenance','MAN-'+assets[op.asset].id.replaceAll('-',''))")}${opButton('Maintenance report',`maintenanceReport(${op.asset})`)}</div></section><section class="panel"><h2>Health & business impact</h2><div class="modal-metrics"><div><small>Condition health</small><h3>${a.health}%</h3></div><div><small>Value at risk</small><h3>EGP ${nfmt(j.status==='Completed'?0:a.cost)}</h3></div></div><p>${a.reading}</p><small>${a.target}</small><div class="insight">${a.risk}. Plan: ${a.due}. This is an illustrative advisory based on sample trend data, not a live prediction.</div><p>Assigned technician: <strong>${people.find(p=>p.id===j.assignee)?.name||'Not assigned'}</strong></p><div class="actions">${opButton('Assign qualified technician',`assignJobDialog(${op.asset})`)}${opButton('Detailed analysis',`predictiveDetail(${op.asset})`)}</div></section></div><div class="analytics-grid" style="margin-top:18px">${analyticsChart(a.id+' condition trend','Illustrative measured condition',scopeData().labels,op.asset===0?[2.6,3,3.5,3.9,4.4,4.8]:op.asset===1?[57,58,59,61,61,62]:[6.1,6.2,6.1,6.2,6.3,6.2],op.asset===0?'mm/s':op.asset===1?'°C':'bar',{target:op.asset===0?4.5:op.asset===1?75:6.5})}${analyticsChart('Maintenance completion','Work orders by state',['Open','Assigned','Completed'],['Open','Assigned','Completed'].map(s=>assets.filter((a,i)=>jobFor(i).status===s).length),'orders',{type:'bar'})}</div>`}
function locateAsset(){op.located=true;op.locationArea=assets[op.asset].area;$('#modal').close();go('Factory Overview')}
function predictiveDetail(i){const a=assets[i];openModal(a.id+' · Condition evidence',`<div class="modal-metrics"><div><small>Advisory</small><h3>${a.risk}</h3></div><div><small>Business exposure</small><h3>EGP ${nfmt(a.cost)}</h3></div></div><p>${a.reading}. ${a.target}.</p><ol class="timeline"><li>Previous inspection: no operational interruption recorded.</li><li>Recent sample trend: ${i===0?'vibration increased from 2.6 to 4.8 mm/s.':'readings remain within the sample operating range.'}</li><li>Suggested window: ${a.due}.</li></ol><p>No remaining-useful-life model is connected. The advisory is rule-based demonstration data.</p><div class="actions">${opButton('Assign inspection',`assignJobDialog(${i})`)}${opButton('Maintenance history',`maintenanceReport(${i})`)}</div>`)}
function pipeView(){openModal('Utility & transfer piping',`<div class="scope-label">${scopeName()} · Illustrative process connections · Select an asset</div><svg class="pipe-diagram" viewBox="0 0 720 300" aria-label="Piping system"><path d="M90 150H220M300 150H430M510 150H630M470 150V60H270V120" stroke="#a2f7d9" stroke-width="8" fill="none"/><g fill="#bfffe31a" stroke="#c6ffe6"><rect x="30" y="95" width="100" height="110" rx="20"/><rect x="590" y="95" width="100" height="110" rx="20"/></g><g fill="#fff" font-size="14" text-anchor="middle"><text x="80" y="150">Feed tank</text><text x="640" y="150">Process tank</text></g>${assets.map((a,i)=>`<g role="button" tabindex="0" onclick="openAssetFromPipe(${i})" onkeydown="if(event.key==='Enter')openAssetFromPipe(${i})" style="cursor:pointer"><circle cx="${260+i*105}" cy="150" r="38" fill="#5c5367" stroke="#bbffe3" stroke-width="2"/><text x="${260+i*105}" y="155" text-anchor="middle" fill="#fff" font-size="14">${a.id}</text></g>`).join('')}<text x="360" y="260" fill="#d8c9da" font-size="12" text-anchor="middle">Schematic only · Not an engineering P&amp;ID</text></svg>`)}
function openAssetFromPipe(i){$('#modal').close();op.asset=i;go('Maintenance')}
function assignJobDialog(i){if(state.factory<0){openModal('Choose a factory','Select the factory for this maintenance assignment. '+factories.map((f,fi)=>`<button class="factory-pick" onclick="state.factory=${fi};render();assignJobDialog(${i})">${f.name} →</button>`).join(''));return}const a=assets[i],eligible=people.filter(p=>p.valid&&p.skills.includes(a.skill));openModal('Assign '+a.id+' maintenance',`<p>${a.name} · Required qualification: <strong>${a.skill}</strong><br>${scopeName()}</p><label>Eligible technician<select id="assignment-person">${eligible.map(p=>`<option value="${p.id}">${p.name} · valid to ${p.expiry}</option>`).join('')}</select></label><label class="note-label">Work instructions<textarea id="assignment-note" rows="3" placeholder="Optional planning notes"></textarea></label><p>Expired or unrelated qualifications are excluded from selection.</p><div class="actions">${opButton('Assign demo work order',`assignJob(${i})`)}${opButton('Review workforce',"$('#modal').close();go('Workforce Mgmt')")}</div>`)}
function assignJob(i){const p=people.find(p=>p.id===$('#assignment-person')?.value),a=assets[i];if(!p||!p.valid||!p.skills.includes(a.skill)||state.factory<0)return;const note=$('#assignment-note')?.value.trim().slice(0,500)||'';saved.jobs[factoryIndex()+'-'+i]={assignee:p.id,status:'Assigned',note,assignedAt:new Date().toISOString()};eventLog(a.id+' assigned to '+p.name,'Maintenance');render();maintenanceReport(i)}
function completeJob(i){const j=jobFor(i);if(!j.assignee||j.status==='Completed')return;saved.jobs[factoryIndex()+'-'+i]={...j,status:'Completed',completedAt:new Date().toISOString()};eventLog(assets[i].id+' inspection completed in demonstration','Maintenance');render();maintenanceReport(i)}
function maintenanceReport(i){const a=assets[i],j=jobFor(i);openModal(a.id+' · Maintenance report',`<article class="maintenance-report"><span class="pill">DEMO WORK ORDER · ${j.status}</span><h3>${a.name}</h3><dl><dt>Factory</dt><dd>${scopeName()}</dd><dt>Required qualification</dt><dd>${a.skill}</dd><dt>Assigned to</dt><dd>${people.find(p=>p.id===j.assignee)?.name||'Not assigned'}</dd><dt>Observed condition</dt><dd>${a.reading}</dd><dt>Planning notes</dt><dd>${escapeHTML(j.note||'No planning notes recorded.')}</dd><dt>Assigned at</dt><dd>${j.assignedAt?new Date(j.assignedAt).toLocaleString():'—'}</dd><dt>Completed at</dt><dd>${j.completedAt?new Date(j.completedAt).toLocaleString():'—'}</dd></dl><h3>History</h3><ol class="timeline"><li>Previous sample inspection: routine check completed.</li>${saved.events.filter(e=>e.factory===factoryIndex()&&e.message.includes(a.id)).map(e=>`<li>${new Date(e.time).toLocaleString()} — ${escapeHTML(e.message)}</li>`).join('')}</ol><div class="actions">${j.status==='Open'?opButton('Assign technician',`assignJobDialog(${i})`):j.status==='Assigned'?opButton('Complete demo inspection',`completeJob(${i})`):''}${opButton('Download report',`downloadMaintenance(${i})`)}</div></article>`)}
function downloadMaintenance(i){const a=assets[i],j=jobFor(i);downloadable(a.id+'-maintenance-report.html',`<!doctype html><html><head><meta charset="UTF-8"><title>${a.id} report</title></head><body style="font:16px Arial;padding:40px"><h1>${a.id} maintenance report</h1><p>Demonstration record · ${scopeName()}</p><p>Status: ${j.status}</p><p>Technician: ${people.find(p=>p.id===j.assignee)?.name||'Unassigned'}</p><p>Condition: ${a.reading}</p><p>Notes: ${escapeHTML(j.note)}</p></body></html>`,'text/html;charset=utf-8')}
function workforceView(){return `<div class="business-strip"><strong>Workforce readiness</strong><span>Match each job to an available person with the required, valid qualification.</span></div><div class="analytics-grid"><section class="panel"><div class="panelhead"><h2>Qualified workforce</h2><small>Sample roster · ${scopeName()}</small></div><div class="table-scroll"><table><tr><th>Person</th><th>Role / skill</th><th>Qualification</th><th>Eligibility</th></tr>${people.map(p=>`<tr><td>${p.name}</td><td>${p.role}<br><small>${p.skills.join(', ')}</small></td><td>${p.expiry}</td><td class="${p.valid?'positive':'warning'}">${p.valid?'Eligible':'Renewal required'}</td></tr>`).join('')}</table></div></section><section class="panel"><h2>Maintenance assignments</h2>${assets.map((a,i)=>{const j=jobFor(i);return `<div class="factory-row"><div class="row"><strong>${a.id} · ${a.skill}</strong><span class="pill">${j.status}</span></div><p>${people.find(p=>p.id===j.assignee)?.name||'Unassigned'}</p><div class="actions">${opButton(j.assignee?'Reassign':'Assign qualified person',`assignJobDialog(${i})`)}${opButton('Job record',`maintenanceReport(${i})`)}</div></div>`}).join('')}</section></div>`}
let cipPhase=saved.cipPhase??1;const cipSteps=['Pre-rinse','Caustic wash','Intermediate rinse','Final rinse','Complete'];
quality=function(){const q=snapshot();return `<div class="business-strip"><strong>Quality outlook</strong><span>Review product quality, cleaning effectiveness and release constraints. Leadership measures remain in Business KPIs.</span></div><div class="analytics-grid"><section class="panel"><div class="panelhead"><h2>CIP · Cleaning-in-place cycle</h2><span class="pill">${cipSteps[cipPhase]}</span></div><div class="cip-phases">${cipSteps.map((x,i)=>`<span class="${i<=cipPhase?'done':''}">${i<cipPhase?'✓ ':''}${x}</span>`).join('')}</div><div class="modal-metrics"><div><small>Wash temperature</small><h3>${cipPhase===1?'78':'42'}°C</h3></div><div><small>Flow</small><h3>18 m³/h</h3></div><div><small>Conductivity</small><h3>${cipPhase===1?'42':'0.8'} mS/cm</h3></div><div><small>Cycle result</small><h3>${cipPhase===4?'Pass · demo':'Pending completion'}</h3></div></div><p>Tank CIP-01 · Recipe CLN-04 · Illustrative validated limits: wash 75–85°C, flow ≥ 15 m³/h, final-rinse conductivity ≤ 1 mS/cm.</p><div class="actions">${opButton(cipPhase===4?'Start new demo cycle':'Advance demo phase','advanceCip()')}${opButton('Cycle history','cipHistory()')}${opButton('Validation checklist',"documentCenter('Quality')")}</div></section><section class="panel"><div class="panelhead"><h2>PAT · Product quality monitoring</h2><span class="pill">Sample measurements</span></div><div class="table-scroll"><table><tr><th>Measure</th><th>Reading</th><th>Acceptance range</th><th>State</th></tr>${[['Blend moisture','2.1%','1.5–2.5%','In range'],['Assay','99.2%','98–102%','In range'],['pH','7.1','6.8–7.4','In range'],['Dissolution','84%','≥ 80%','In range']].map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td><td class="positive">${r[3]}</td></tr>`).join('')}</table></div><div class="insight">Measurements are simulated. A batch hold remains until an explicit review action in Process; the dashboard does not automatically release production.</div><div class="actions">${opButton('Review held batches',"go('Process')")}${opButton('Quality report',"reportCenter()")}</div></section>${analyticsChart('Moisture trend','PAT sample trend',scopeData().labels,[2.3,2.2,2.2,2.1,2,2.1],'%',{target:2.5})}${analyticsChart('First-pass yield','Product acceptance by line',['Line 1','Line 2','Line 3'],[q.quality+.3,q.quality-.4,q.quality+.1],'%',{type:'bar',target:98})}</div>`};
function advanceCip(){cipPhase=cipPhase===4?0:cipPhase+1;saved.cipPhase=cipPhase;eventLog('CIP-01 demo phase: '+cipSteps[cipPhase],'Quality');render()}
function cipHistory(){openModal('CIP cycle history',`<table><tr><th>Cycle</th><th>Recipe</th><th>Result</th></tr><tr><td>CIP-0261</td><td>CLN-04</td><td>${cipPhase===4?'Pass':'In progress'}</td></tr><tr><td>CIP-0260</td><td>CLN-04</td><td>Pass · sample record</td></tr><tr><td>CIP-0259</td><td>CLN-04</td><td>Review completed · sample record</td></tr></table><ol class="timeline">${saved.events.filter(e=>e.area==='Quality').map(e=>`<li>${new Date(e.time).toLocaleString()} — ${escapeHTML(e.message)}</li>`).join('')||'<li>No local demo cycle actions yet.</li>'}</ol>`)}
function facilityView(){const systems=[{name:'Building operations',read:'98% controlled areas ready',measures:[['Cleanroom temperature','21.4°C','20–24°C'],['Humidity','46%','40–55%'],['Room pressure','15 Pa','10–20 Pa']]},{name:'Power & energy',read:'1.24 MW current demand',measures:[['Demand','1.24 MW','Budget 1.4 MW'],['Power factor','0.97','Target > 0.95'],['Backup readiness','Available','Routine test complete']]},{name:'Utilities',read:'No critical interruption',measures:[['Chilled water','6.8°C','6–8°C'],['Compressed air','6.2 bar','6–6.5 bar'],['Steam readiness','Available','Within sample limits']]}];return `<div class="business-strip"><strong>Facility readiness</strong><span>Connect environmental compliance, utility reliability and spend to production continuity.</span></div><div class="entity-grid">${systems.map((s,i)=>`<button class="entity" onclick="facilityDetail(${i})"><div class="entity-icon">${['⌂','ϟ','◉'][i]}</div><strong>${s.name}</strong><small>${s.read}</small><div class="insight">Open system details →</div></button>`).join('')}</div><div class="analytics-grid" style="margin-top:18px">${analyticsChart('Utility demand','Illustrative facility load',scopeData().labels,[1.1,1.18,1.24,1.3,1.25,1.24],'MW',{target:1.4})}<section class="panel"><h2>Facility actions</h2><div class="insight">AHU-03 filter inspection is due. Schedule the work before room readiness is affected.</div><div class="actions">${opButton('Facility alarms','alarmCenter()')}${opButton('Building documents',"documentCenter('Factory')")}${opButton('Utility piping','pipeView()')}${opButton('Camera views','cameraCenter()')}</div></section></div>`}
function facilityDetail(i){const groups=[[['Cleanroom temperature','21.4°C','20–24°C'],['Relative humidity','46%','40–55%'],['Differential pressure','15 Pa','10–20 Pa']],[['Demand','1.24 MW','Budget 1.4 MW'],['Power factor','0.97','Target > 0.95'],['Backup readiness','Available','Test complete']],[['Chilled water','6.8°C','6–8°C'],['Compressed air','6.2 bar','6–6.5 bar'],['Steam readiness','Available','Within sample range']]];openModal(['Building operations','Power & energy','Utilities'][i],`<div class="scope-label">${scopeName()} · Simulated system data</div><table><tr><th>Parameter</th><th>Reading</th><th>Operating target</th></tr>${groups[i].map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td></tr>`).join('')}</table><div class="actions">${opButton('Documents',"documentCenter('Factory')")}${opButton('Alarm history','alarmCenter()')}</div>`)}
function cameraScene(i){return `<svg class="camera-scene" viewBox="0 0 640 330" aria-label="Simulated ${['gate','production corridor','packaging floor','warehouse'][i]} view"><defs><linearGradient id="room${i}" x2="1" y2="1"><stop stop-color="#85958f"/><stop offset="1" stop-color="#363f43"/></linearGradient></defs><path d="M0 0H640V330H0Z" fill="url(#room${i})"/><path d="M0 330 220 140H430L640 330Z" fill="#b5bab3"/><path d="M0 0 220 140v190L0 330ZM640 0 430 140v190L640 330Z" fill="#6a7774"/><path d="M0 0H640L430 140H220Z" fill="#ced8d0"/>${[0,1,2].map(n=>`<path d="M${40+n*190} 80L${80+n*150} 95V260L${40+n*190} 285Z" fill="#9db4aa" stroke="#e0eae2"/><path d="M${70+n*170} 215h85v45h-85z" fill="#667b75" stroke="#b7cbc2"/>`).join('')}<rect x="230" y="60" width="170" height="9" fill="#e5ffe9"/><text x="18" y="25" fill="white" font-size="14">SIMULATED CAMERA VIEW · CAM-0${i+1}</text><text x="18" y="310" fill="white" font-size="12">${['Main gate','Production corridor','Packaging floor','Warehouse'][i]} · Illustrative scene, not live CCTV</text></svg>`}
function cameraCenter(i=op.camera){op.camera=i;const key=factoryIndex()+'-'+i,url=saved.cameras[key]||'';openModal('Camera views',`<div class="scope-label">${state.factory<0?'Default demo site: '+factories[0].name:scopeName()} · ${url?'Configured image snapshot source':'Simulated scene — no live camera connected'}</div><div class="camera-layout"><aside>${['Main gate','Production corridor','Packaging floor','Warehouse'].map((s,n)=>`<button class="${i===n?'active':''}" onclick="cameraCenter(${n})">CAM-0${n+1} · ${s}</button>`).join('')}</aside><div>${url?`<img class="camera-snapshot" src="${escapeHTML(url)}" alt="Configured camera snapshot" onerror="this.alt='Camera snapshot unavailable; verify the source URL'">`:cameraScene(i)}</div></div><details><summary>Configure an image snapshot endpoint</summary><p>Use an HTTPS image snapshot URL. Streaming protocols and authenticated camera gateways require a backend adapter.</p><div class="filter-row"><input id="camera-url" type="url" placeholder="https://camera.example/snapshot.jpg" value="${escapeHTML(url)}">${opButton('Save source',`saveCamera(${i})`)}${opButton('Use demo scene',`resetCamera(${i})`)}</div><span id="camera-feedback" class="warning"></span></details>`);$('#modal').classList.add('wide-modal')}
function saveCamera(i){if(state.factory<0){$('#camera-feedback').textContent='Select a specific factory before saving a camera source.';return}try{const u=new URL($('#camera-url').value);if(u.protocol!=='https:')throw Error();saved.cameras[factoryIndex()+'-'+i]=u.href;persist();cameraCenter(i)}catch{$('#camera-feedback').textContent='Enter a valid HTTPS image URL.'}}
function resetCamera(i){delete saved.cameras[factoryIndex()+'-'+i];persist();cameraCenter(i)}
async function weatherCenter(){const f=factoryIndex(),coord=coordinates[f];openModal('Weather · '+factories[f].city,'<div id="weather-result">Loading current weather…</div><p class="note">External weather requires internet access. Factory coordinates are illustrative.</p>');try{const url=`https://api.open-meteo.com/v1/forecast?latitude=${coord[0]}&longitude=${coord[1]}&current=temperature_2m,relative_humidity_2m,wind_speed_10m&timezone=Africa%2FCairo`,res=await fetch(url);if(!res.ok)throw Error();const data=await res.json(),c=data.current,el=$('#weather-result');if(!el)return;el.innerHTML=`<div class="modal-metrics"><div><small>Temperature</small><h3>${Number(c.temperature_2m)}°C</h3></div><div><small>Humidity</small><h3>${Number(c.relative_humidity_2m)}%</h3></div><div><small>Wind</small><h3>${Number(c.wind_speed_10m)} km/h</h3></div></div><p>Weather time: ${escapeHTML(c.time)} · Africa/Cairo</p><p class="insight">Review cooling demand, outdoor maintenance and transport exposure alongside current weather.</p><small>Weather data by <a href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo</a>. Model-derived current conditions.</small>`}catch{const el=$('#weather-result');if(el)el.innerHTML='<p class="warning">Weather is unavailable. Check internet access and retry.</p>'+opButton('Retry','weatherCenter()')}}
function reportRows(kind){if(kind==='alarms')return visibleAlarms().map(a=>({id:a.id,factory:factories[a.factory].name,area:a.area,severity:a.severity,status:alarmStatus(a.id),business_impact:a.impact}));if(kind==='maintenance')return assets.map((a,i)=>({asset:a.id,factory:scopeName(),qualification:a.skill,assigned_to:people.find(p=>p.id===jobFor(i).assignee)?.name||'Unassigned',status:jobFor(i).status}));if(kind==='batches')return scopedBatches(true).map(b=>({id:b.id,factory:factories[b.factory].name,line:b.line+1,product:b.product,stage:batchStages[b.stage],status:b.status}));return lineSpecs.map((_,i)=>{const l=lineData(i);return {factory:scopeName(),period:$('#period').value,line:i+1,product:l.product,target_units:l.target,produced_units:l.output,utilization:l.utilization,reject_rate:l.reject}})}
function reportCenter(kind='production'){op.reportKind=kind;const rows=reportRows(kind),headers=Object.keys(rows[0]||{});openModal('Reports & exports',`<div class="filter-row"><label>Report<select onchange="reportCenter(this.value)">${['production','alarms','maintenance','batches'].map(x=>`<option ${x===kind?'selected':''}>${x}</option>`).join('')}</select></label><span>${scopeName()} · ${$('#period').value} · Demo data</span></div><div class="table-scroll"><table><tr>${headers.map(h=>`<th>${h.replaceAll('_',' ')}</th>`).join('')}</tr>${rows.map(r=>`<tr>${headers.map(h=>`<td>${escapeHTML(r[h])}</td>`).join('')}</tr>`).join('')}</table></div><div class="actions">${opButton('Download CSV',`exportReport('${kind}')`)}${opButton('Print / save PDF',`printReport('${kind}')`)}${opButton('Include performance charts',`printReport('${kind}',true)`)}</div><p class="note">Exports contain the selected scope and current demo records. PDF uses the browser print dialog.</p>`);$('#modal').classList.add('wide-modal')}
function exportReport(kind){const rows=reportRows(kind),keys=Object.keys(rows[0]||{}),csv=[keys,...rows.map(r=>keys.map(k=>r[k]))].map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');downloadable('life-science-'+kind+'.csv','\ufeff'+csv)}
function printReport(kind,charts=false){const rows=reportRows(kind),keys=Object.keys(rows[0]||{}),chart=charts?analyticsChart('Output per packaging line','Demo performance',['Line 1','Line 2','Line 3'],lineSpecs.map((_,i)=>lineData(i).output/1000),'k units',{type:'bar'}):'';printHTML(`<!doctype html><html><head><meta charset="UTF-8"><title>Life Science ${kind} report</title><style>body{font:13px Arial;margin:35px;color:#29343d}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccd5db;padding:8px;text-align:left}.analytics-svg{width:650px;height:250px}.analytics-svg text{fill:#333}button,.chart-caption{display:none}h1{font-size:25px}small{color:#667}</style></head><body><h1>Life Science · ${kind} report</h1><p>${scopeName()} · ${$('#period').value} · ${new Date().toLocaleString()}</p><small>Demonstration data — not a production record</small><table><tr>${keys.map(k=>`<th>${k.replaceAll('_',' ')}</th>`).join('')}</tr>${rows.map(r=>`<tr>${keys.map(k=>`<td>${escapeHTML(r[k])}</td>`).join('')}</tr>`).join('')}</table>${chart}</body></html>`)}
const priorBusinessSection=businessSection;businessSection=function(){if(state.tab==='Maintenance')return maintenanceView();if(state.tab==='Workforce Mgmt')return workforceView();if(state.tab==='Facility')return facilityView();return priorBusinessSection()};
const priorBuildMap=buildMap;buildMap=function(){priorBuildMap();const bar=$('.map-bottom');if(bar){bar.insertAdjacentHTML('beforeend',opButton('Weather','weatherCenter()'));} };
const priorAction=openAction;openAction=function(i){if(i===1){assignJobDialog(0);return}if(i===2){$('#modal').close();go('Workforce Mgmt');return}openModal('Packaging recovery plan',`<p>Line 2 changeover is reducing output. Two sample orders are flagged for review.</p><ol class="timeline"><li>Review the current changeover stage.</li><li>Prioritize the earliest delivery commitments.</li><li>Confirm quality readiness before packaging resumes.</li></ol><div class="actions">${opButton('Inspect line 2',"$('#modal').close();state.line=1;go('Packaging')")}${opButton('Review batches',"$('#modal').close();state.line=1;go('Process')")}${opButton('Export delivery exposure',"exportReport('production')")}</div>`)};
const priorOperationsRender=render;render=function(){window.disposeOperationsModels?.();priorOperationsRender();$('#modal').classList.remove('wide-modal');if(state.tab!=='Overview'){$('.title')?.insertAdjacentHTML('afterend',`<div class="workspace-tools"><span><span class="dot"></span> Interactive demonstration · ${scopeName()}</span><div>${opButton('Documents','documentCenter()')}${opButton('Alarms','alarmCenter()')}${opButton('Reports','reportCenter()')}${opButton('Cameras','cameraCenter()')}</div></div>`);document.querySelectorAll('.pack-gauges .compact-gauge').forEach((e,i)=>e.onclick=()=>openModal(['Availability','Performance','Quality'][i]+' · Line '+(state.line+1),`<div class="metric-reading">${[lineData(state.line).availability,lineData(state.line).performance,lineData(state.line).quality][i]}%</div><p>${['Run time as a share of planned production time.','Actual operating pace relative to the planned rate.','Accepted units as a share of total units produced.'][i]}</p>`))}if(state.tab==='Factory Overview'){const strips=document.querySelectorAll('.business-strip');if(strips.length>1)strips[0].remove()}window.mountOperationsModels?.()};
function resetModel(kind){window.resetOperationsModel?.(kind)}
render();
